#!/usr/bin/env python3
"""
Comprehensive test script to verify the quote handling fix.
"""

import tempfile
import pathlib
import json
from mbed_tools.build._internal.cmake_file import generate_mbed_config_cmake_file
from mbed_tools.build._internal.config.config import Config
from tests.build._internal.config.factories import SourceFactory


def test_various_quote_scenarios():
    """Test various scenarios with quotes, braces, and parentheses."""

    print("=== Comprehensive Quote Handling Test ===")

    test_cases = [
        {
            "name": "Original issue case",
            "config": {
                "iotc-mqtt-host": {
                    "help": "IOTC MQTT host configuration",
                    "value": "{\"mqtt.2030.ltsapis.goog\", IOTC_MQTT_PORT}",
                    "macro_name": "IOTC_MQTT_HOST"
                }
            }
        },
        {
            "name": "Simple string with no special chars",
            "config": {
                "simple-value": {
                    "value": "hello world",
                    "macro_name": "SIMPLE_VALUE"
                }
            }
        },
        {
            "name": "Value with braces only",
            "config": {
                "brace-value": {
                    "value": "{test_value}",
                    "macro_name": "BRACE_VALUE"
                }
            }
        },
        {
            "name": "Value with parentheses only", 
            "config": {
                "paren-value": {
                    "value": "(test_value)",
                    "macro_name": "PAREN_VALUE"
                }
            }
        },
        {
            "name": "Value with quotes only",
            "config": {
                "quote-value": {
                    "value": '"quoted_string"',
                    "macro_name": "QUOTE_VALUE"
                }
            }
        },
        {
            "name": "Complex case with multiple quote types",
            "config": {
                "complex-value": {
                    "value": '{"key": "value", "port": 8883}',
                    "macro_name": "COMPLEX_VALUE"
                }
            }
        },
        {
            "name": "Nested braces with quotes",
            "config": {
                "nested-value": {
                    "value": "{{\"inner\": \"value\"}}",
                    "macro_name": "NESTED_VALUE"
                }
            }
        }
    ]

    # Create minimal target attributes
    target_attributes = {
        "labels": [],
        "extra_labels": [],
        "features": [],
        "components": [],
        "macros": [],
        "device_has": [],
        "c_lib": "std",
        "core": "Cortex-M4",
        "printf_lib": "minimal-printf",
        "supported_form_factors": [],
        "supported_c_libs": {"gcc_arm": ["std"]},
        "supported_application_profiles": ["full"],
    }

    for i, test_case in enumerate(test_cases):
        print(f"\n--- Test Case {i+1}: {test_case['name']} ---")

        # Create source with test config
        source = SourceFactory(config=test_case['config'])

        # Build the config
        config = Config.from_sources([source])

        # Generate the CMake file content
        cmake_content = generate_mbed_config_cmake_file(
            "TEST_TARGET", 
            target_attributes, 
            config, 
            "GCC_ARM"
        )

        # Extract and show the relevant lines
        lines = cmake_content.split('\n')
        in_config_section = False

        for line in lines:
            if "MBED_CONFIG_DEFINITIONS" in line:
                in_config_section = True
            elif in_config_section:
                if ");" in line:  # End of the definitions section
                    break
                elif "-D" in line and line.strip():
                    print(f"  Generated: {line.strip()}")

                    # Basic validation - should not start with quote
                    if line.strip().startswith('"'):
                        print(f"  ❌ ERROR: Line starts with quote!")
                    else:
                        print(f"  ✅ OK: Line properly formatted")


def test_macro_definitions():
    """Test macro definitions separately."""

    print("\n\n=== Macro Definition Test ===")

    # Test macros with values
    source = SourceFactory(
        macros=[
            "SIMPLE_MACRO=123",
            'STRING_MACRO="hello"', 
            'COMPLEX_MACRO={"key": "value"}'
        ]
    )

    # Build the config
    config = Config.from_sources([source])

    # Create minimal target attributes
    target_attributes = {
        "labels": [],
        "extra_labels": [],
        "features": [],
        "components": [],
        "macros": [],
        "device_has": [],
        "c_lib": "std",
        "core": "Cortex-M4", 
        "printf_lib": "minimal-printf",
        "supported_form_factors": [],
        "supported_c_libs": {"gcc_arm": ["std"]},
        "supported_application_profiles": ["full"],
    }

    # Generate the CMake file content
    cmake_content = generate_mbed_config_cmake_file(
        "TEST_TARGET", 
        target_attributes, 
        config, 
        "GCC_ARM"
    )

    # Extract and show the relevant lines
    lines = cmake_content.split('\n')
    in_config_section = False

    print("Generated macro definitions:")
    for line in lines:
        if "MBED_CONFIG_DEFINITIONS" in line:
            in_config_section = True
        elif in_config_section:
            if ");" in line:  # End of the definitions section
                break
            elif "-D" in line and line.strip():
                print(f"  {line.strip()}")

                # Basic validation
                if line.strip().startswith('"'):
                    print(f"  ❌ ERROR: Line starts with quote!")
                else:
                    print(f"  ✅ OK: Line properly formatted")


if __name__ == "__main__":
    test_various_quote_scenarios()
    test_macro_definitions()
    print("\n=== Test Summary ===")
    print("All tests completed. Check output above for any errors.")

